<div class="rounded-xl border bg-slate-50 p-4 space-y-3" data-item><div class="flex justify-end"><button type="button" data-remove-item class="text-xs font-bold text-red-600">Remove item</button></div><div class="grid gap-3 sm:grid-cols-2"><div><label class="field">Badge / step number</label><input name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][badge]" value="{{ $item['badge']??'' }}"></div><div><label class="field">Title / question</label><input name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][title]" value="{{ $item['title']??'' }}"></div></div><div><label class="field">Body / answer</label><textarea name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][body]" rows="3">{{ $item['body']??'' }}</textarea></div><div class="grid gap-3 sm:grid-cols-2"><div><label class="field">Link label</label><input name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][link_label]" value="{{ $item['link_label']??'' }}"></div><div><label class="field">Link URL</label><input name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][link_url]" value="{{ $item['link_url']??'' }}"></div><div><label class="field">Optional image</label><input type="file" name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][image]" accept="image/jpeg,image/png,image/webp"><input type="hidden" name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][existing_image_path]" value="{{ $item['existing_image_path']??'' }}"></div><div><label class="field">Image alt text</label><input name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][image_alt]" value="{{ $item['image_alt']??'' }}"></div></div></div>
